import hashlib
import hmac
import time
import os
import sqlite3
import threading
from functools import wraps
from flask import Flask, request, jsonify, g, session
import bcrypt

app = Flask(__name__)
app.secret_key = os.urandom(32)

DB_PATH = '/tmp/secure_app.db'
RATE_LIMIT_WINDOW = 60
MAX_ATTEMPTS = 5

# Thread-local storage for database connections
_local = threading.local()

def get_db():
    if not hasattr(_local, 'connection'):
        _local.connection = sqlite3.connect(DB_PATH)
        _local.connection.row_factory = sqlite3.Row
    return _local.connection

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        failed_attempts INTEGER DEFAULT 0,
        locked_until REAL DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        session_id TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        role TEXT NOT NULL,
        created_at REAL NOT NULL,
        expires_at REAL NOT NULL,
        metadata TEXT DEFAULT '{}'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        details TEXT,
        timestamp REAL
    )''')
    db.commit()
    db.close()

init_db()

# Rate limiting storage
_rate_limits = {}
_rate_lock = threading.Lock()

def check_rate_limit(identifier):
    """Check if the identifier has exceeded rate limits."""
    now = time.time()
    with _rate_lock:
        if identifier not in _rate_limits:
            _rate_limits[identifier] = []
        # Clean old entries
        _rate_limits[identifier] = [
            t for t in _rate_limits[identifier] if t > now - RATE_LIMIT_WINDOW
        ]
        if len(_rate_limits[identifier]) >= MAX_ATTEMPTS:
            return False
        _rate_limits[identifier].append(now)
    return True

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def create_session_token(user_id, role):
    """Create a cryptographically secure session token."""
    token_bytes = os.urandom(32)
    token = token_bytes.hex()
    now = time.time()
    db = get_db()
    db.execute(
        'INSERT INTO sessions (session_id, user_id, role, created_at, expires_at) VALUES (?, ?, ?, ?, ?)',
        (token, user_id, role, now, now + 3600)
    )
    db.commit()
    return token

def validate_session(token):
    """Validate session token and return session data."""
    if not token or not isinstance(token, str) or len(token) != 64:
        return None
    db = get_db()
    row = db.execute(
        'SELECT * FROM sessions WHERE session_id = ?', (token,)
    ).fetchone()
    if not row:
        return None
    if time.time() > row['expires_at']:
        db.execute('DELETE FROM sessions WHERE session_id = ?', (token,))
        db.commit()
        return None
    return dict(row)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token', '')
        session_data = validate_session(token)
        if not session_data:
            return jsonify({'error': 'Authentication required'}), 401
        g.session = session_data
        g.user_id = session_data['user_id']
        return f(*args, **kwargs)
    return decorated

def require_role(required_role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if not hasattr(g, 'session'):
                return jsonify({'error': 'Authentication required'}), 401
            session_role = g.session.get('role', 'user')
            if not check_role_hierarchy(session_role, required_role):
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

def check_role_hierarchy(user_role, required_role):
    """Check if user_role meets or exceeds required_role in hierarchy."""
    hierarchy = {'user': 0, 'moderator': 1, 'admin': 2, 'superadmin': 3}
    user_level = hierarchy.get(user_role, 0)
    required_level = hierarchy.get(required_role, 99)
    return user_level >= required_level

@app.route('/api/auth/login', methods=['POST'])
def login():
    """Authenticate user and create session."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    # Rate limiting by IP
    client_ip = request.remote_addr
    if not check_rate_limit(f'login:{client_ip}'):
        return jsonify({'error': 'Too many attempts'}), 429

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?', (username,)
    ).fetchone()

    if not user:
        # Constant-time comparison even for non-existent users
        bcrypt.checkpw(b'dummy', b'$2b$12$LJ3m4sMKfRzlTEhTyOdMIuBRGHGv5bFDmMiYqQC5.3YbLMgKfxYa6')
        return jsonify({'error': 'Invalid credentials'}), 401

    # Check account lockout
    if user['locked_until'] > time.time():
        return jsonify({'error': 'Account locked'}), 423

    if not bcrypt.checkpw(password.encode('utf-8'), user['password_hash'].encode('utf-8')):
        # Increment failed attempts
        new_attempts = user['failed_attempts'] + 1
        locked_until = 0
        if new_attempts >= MAX_ATTEMPTS:
            locked_until = time.time() + 300  # 5 minute lockout
        db.execute(
            'UPDATE users SET failed_attempts = ?, locked_until = ? WHERE id = ?',
            (new_attempts, locked_until, user['id'])
        )
        db.commit()
        return jsonify({'error': 'Invalid credentials'}), 401

    # Reset failed attempts on success
    db.execute(
        'UPDATE users SET failed_attempts = 0, locked_until = 0 WHERE id = ?',
        (user['id'],)
    )
    db.commit()

    token = create_session_token(user['id'], user['role'])
    return jsonify({'token': token, 'role': user['role']})

