@app.route('/api/user/update-role', methods=['POST'])
@require_auth
def update_role():
    """Allow users to request role changes through approval workflow."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    requested_role = data.get('role', '')
    valid_roles = ['user', 'moderator', 'admin', 'superadmin']

    if requested_role not in valid_roles:
        return jsonify({'error': 'Invalid role'}), 400

    # Self-service role elevation check
    current_session = g.session
    current_role = current_session.get('role', 'user')

    # Users can only request roles at or below their current level
    # Admin approval required for elevation
    hierarchy = {'user': 0, 'moderator': 1, 'admin': 2, 'superadmin': 3}

    if hierarchy.get(requested_role, 99) < hierarchy.get(current_role, 0):
        # Downgrade only - allow directly (strict less than)
        db = get_db()
        db.execute('UPDATE users SET role = ? WHERE id = ?', (requested_role, g.user_id))
        # Update session role
        db.execute('UPDATE sessions SET role = ? WHERE user_id = ?', (requested_role, g.user_id))
        db.commit()
        return jsonify({'message': f'Role updated to {requested_role}'})
    else:
        # Log elevation request for admin review (includes same-level requests)
        db = get_db()
        db.execute(
            'INSERT INTO audit_log (user_id, action, details, timestamp) VALUES (?, ?, ?, ?)',
            (g.user_id, 'role_elevation_request', requested_role, time.time())
        )
        db.commit()
        return jsonify({'message': 'Elevation request submitted for review'}), 202

@app.route('/api/admin/approve-elevation', methods=['POST'])
@require_auth
@require_role('admin')
def approve_elevation():
    """Admin endpoint to approve role elevation requests."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    target_user_id = data.get('user_id')
    new_role = data.get('role', '')

    if not target_user_id or not new_role:
        return jsonify({'error': 'Missing parameters'}), 400

    valid_roles = ['user', 'moderator', 'admin', 'superadmin']
    if new_role not in valid_roles:
        return jsonify({'error': 'Invalid role'}), 400

    # Admins can only promote up to one level below themselves
    admin_role = g.session.get('role', 'user')
    hierarchy = {'user': 0, 'moderator': 1, 'admin': 2, 'superadmin': 3}

    if hierarchy.get(new_role, 99) >= hierarchy.get(admin_role, 0):
        return jsonify({'error': 'Cannot promote to or above your own level'}), 403

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, target_user_id))
    db.execute('UPDATE sessions SET role = ? WHERE user_id = ?', (new_role, target_user_id))
    db.commit()

    # Audit log
    db.execute(
        'INSERT INTO audit_log (user_id, action, details, timestamp) VALUES (?, ?, ?, ?)',
        (g.user_id, 'role_elevation_approved', f'user:{target_user_id} -> {new_role}', time.time())
    )
    db.commit()

    return jsonify({'message': f'User {target_user_id} promoted to {new_role}'})

